import React, { useState } from 'react';
import { Link } from 'react-router-dom';

function EmotionRecommendPage() {
  const [inputText, setInputText] = useState('');
  const [recommendedMovie, setRecommendedMovie] = useState(null);
  const [loading, setLoading] = useState(false);

  const emotionDatabase = [
    {
      keywords: ['위로', '슬픔', '울적', '지침', '휴식', '힐링', '마음'],
      title: '싱 어 게인',
      genre: '드라마 / 음악',
      reason: '지친 마음을 부드럽게 감싸줄 따뜻한 음악과 위로가 담긴 영화예요.',
      poster: '/img/00/01.jpg'
    },
    {
      keywords: ['짜릿', '스릴', '긴장', '액션', '시원', '답답'],
      title: '오디세이',
      genre: 'SF / 어드벤처',
      reason: '답답한 일상을 날려버릴 압도적인 스케일과 몰입감을 선사합니다.',
      poster: '/img/00/04.jpg'
    },
    {
      keywords: ['설렘', '사랑', '로맨스', '기분좋아', '행복', '재미'],
      title: '아가씨',
      genre: '매혹 / 스릴러',
      reason: '눈을 뗄 수 없는 매혹적인 스토리로 기분 좋은 긴장감을 채워줄 거예요.',
      poster: '/img/00/02.jpg'
    }
  ];

  const handleRecommend = (e) => {
    e.preventDefault();
    if (!inputText.trim()) {
      alert('오늘의 감정을 간단히 적어주세요!');
      return;
    }

    setLoading(true);
    setRecommendedMovie(null);

    setTimeout(() => {
      let matched = emotionDatabase.find((item) =>
        item.keywords.some((keyword) => inputText.includes(keyword))
      );

      if (!matched) {
        matched = emotionDatabase[0];
      }

      setRecommendedMovie(matched);
      setLoading(false);
    }, 600);
  };

  return (
    <div className="w-full min-h-screen bg-[#eef0f4] py-16 px-6 flex flex-col items-center justify-center font-sans text-zinc-800">
      <div className="w-full max-w-xl space-y-8">
        
        {/* 상단 타이틀 영역 */}
        <div className="text-center space-y-2">
          <span className="text-xs font-bold tracking-widest text-zinc-400 uppercase">
            MEGABOX GLASS UI
          </span>
          <h2 className="text-3xl font-black text-zinc-700 tracking-tight">
            오늘의 감정에 영화를 선물하세요
          </h2>
        </div>

        {/* 1. 글래스모피즘 검색/입력 박스 (이미지의 Search 바 스타일) */}
        <form onSubmit={handleRecommend} className="w-full">
          <div className="relative flex items-center bg-white/40 backdrop-blur-md border border-white/80 rounded-full shadow-[0_8px_32px_0_rgba(31,38,135,0.07)] p-2 px-6 transition-all focus-within:bg-white/60 focus-within:shadow-[0_8px_32px_0_rgba(31,38,135,0.15)]">
            <svg className="w-5 h-5 text-zinc-400 mr-3 shrink-0" fill="none" stroke="currentColor" strokeWidth="2.5" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z"></path>
            </svg>
            <input 
              type="text" 
              value={inputText}
              onChange={(e) => setInputText(e.target.value)}
              placeholder="오늘 어떤 감정을 느끼셨나요? (예: 위로, 액션)" 
              className="w-full bg-transparent text-sm text-zinc-700 font-bold placeholder-zinc-400 focus:outline-none py-3"
            />
            {/* 글래스 버튼 스타일 */}
            <button 
              type="submit" 
              className="ml-3 px-6 py-3 bg-gradient-to-r from-blue-500/80 to-blue-600/80 hover:from-blue-600 hover:to-blue-700 text-white font-bold text-xs rounded-full shadow-[0_4px_15px_rgba(59,130,246,0.4)] backdrop-blur-sm transition transform active:scale-95 shrink-0"
            >
              추천받기
            </button>
          </div>
        </form>

        {/* 로딩 애니메이션 */}
        {loading && (
          <div className="text-center py-10 text-blue-500 font-bold animate-pulse text-sm">
            유리알 감정을 분석하는 중입니다...
          </div>
        )}

        {/* 2. 글래스모피즘 추천 결과 카드 (이미지의 Recommendations 박스 스타일) */}
        {recommendedMovie && !loading && (
          <div className="bg-white/40 backdrop-blur-xl border border-white/90 rounded-[35px] p-8 shadow-[0_20px_50px_rgba(0,0,0,0.08)] flex flex-col md:flex-row items-center gap-6 transition-all animate-fade-in">
            
            {/* 포스터 프레임 */}
            <div className="w-32 h-44 rounded-2xl bg-white/60 border border-white shadow-inner overflow-hidden shrink-0 flex items-center justify-center">
              {recommendedMovie.poster ? (
                <img src={recommendedMovie.poster} alt={recommendedMovie.title} className="w-full h-full object-cover" />
              ) : (
                <span className="text-[11px] text-zinc-400 font-medium">Poster</span>
              )}
            </div>

            {/* 컨텐츠 영역 */}
            <div className="flex flex-col justify-center space-y-3 text-left w-full">
              <div className="flex items-center justify-between">
                <span className="text-[10px] font-black uppercase tracking-wider text-blue-600 bg-blue-500/10 px-3 py-1 rounded-full border border-blue-500/20">
                  {recommendedMovie.genre}
                </span>
                <button 
                  onClick={() => setRecommendedMovie(null)} 
                  className="text-xs text-zinc-400 hover:text-zinc-600 font-bold"
                >
                  ✕ 닫기
                </button>
              </div>

              <h3 className="text-2xl font-black text-zinc-800 tracking-tight">
                {recommendedMovie.title}
              </h3>

              <p className="text-xs text-zinc-500 font-medium leading-relaxed">
                "{recommendedMovie.reason}"
              </p>

              {/* 하단 글래스 버튼 */}
              <div className="pt-2 flex gap-3">
                <Link 
                  to="/schedule" 
                  className="flex-1 text-center py-3 bg-white/80 hover:bg-white text-zinc-700 font-bold text-xs rounded-2xl border border-white shadow-[0_4px_12px_rgba(0,0,0,0.05)] transition"
                >
                  상영시간표 보기
                </Link>
              </div>
            </div>

          </div>
        )}

      </div>
    </div>
  );
}

export default EmotionRecommendPage;
